#!/usr/bin/env python3
"""Apply a checked source-only merge of the two tested indexing branches."""
from pathlib import Path
import base64, hashlib, json, lzma, difflib
R=Path(__file__).resolve().parents[1]
DATA=''''''
blob=base64.b64decode(DATA,validate=True)
assert hashlib.sha256(blob).hexdigest()=='f36bc1bb494ef91d3e2e06059c59211ee5c7b6e9f949682eed996eca815a699a'
pending={};patch=''
for name,item in json.loads(lzma.decompress(blob)).items():
 p=Path(name);assert not p.is_absolute() and '..' not in p.parts
 old=(R/p).read_text() if (R/p).exists() else ''
 assert (hashlib.sha256(old.encode()).hexdigest()==item['base']) if item['base'] else not (R/p).exists(),name
 lines=old.splitlines(True);end=len(lines)
 for start,stop,text in reversed(item['edits']):
  assert 0<=start<=stop<=end;lines[start:stop]=text.splitlines(True);end=start
 new=''.join(lines);assert hashlib.sha256(new.encode()).hexdigest()==item['after'],name
 pending[p]=new
 patch+=''.join(difflib.unified_diff(old.splitlines(True),lines,fromfile='a/'+name,tofile='b/'+name))
for p,text in pending.items():(R/p).parent.mkdir(parents=True,exist_ok=True);(R/p).write_text(text)
(R/'4.6.5-to-4.6.6.patch').write_text(patch)
print('Verified and applied',len(pending),'combined source/support changes')
